--
-- Name: attention_items_sync(); Type: FUNCTION; Schema: demo_eyfs; Owner: -
--

CREATE FUNCTION demo_eyfs.attention_items_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.rag        := COALESCE(NEW.rag, NEW.severity, 'amber');
    NEW.severity   := COALESCE(NEW.severity, NEW.rag);
    NEW.action_url := COALESCE(NEW.action_url, NEW.link);
    NEW.link       := COALESCE(NEW.link, NEW.action_url);
  ELSE
    IF    NEW.rag      IS DISTINCT FROM OLD.rag      THEN NEW.severity := NEW.rag;
    ELSIF NEW.severity IS DISTINCT FROM OLD.severity THEN NEW.rag      := NEW.severity;
    END IF;
    IF    NEW.action_url IS DISTINCT FROM OLD.action_url THEN NEW.link       := NEW.action_url;
    ELSIF NEW.link       IS DISTINCT FROM OLD.link       THEN NEW.action_url := NEW.link;
    END IF;
  END IF;

  -- status is derived from resolved_at / snoozed_until, so a caller that only
  -- knows one vocabulary still leaves the row consistent.
  IF NEW.resolved_at IS NOT NULL THEN
    NEW.status := 'done';
  ELSIF NEW.snoozed_until IS NOT NULL AND NEW.snoozed_until > now() THEN
    NEW.status := 'snoozed';
  ELSIF NEW.status = 'done' AND NEW.resolved_at IS NULL THEN
    -- Two different situations reach this branch and they need opposite answers.
    -- A caller CLOSING the row b236-style sets status='done' and leaves
    -- resolved_at alone: give it a resolved_at. A caller REOPENING the row sets
    -- resolved_at=NULL and leaves the stale status='done' behind: honour the
    -- reopen. Without the TG_OP/OLD test the trigger simply undid every reopen,
    -- and the refresh could never bring an auto-closed item back.
    IF TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'done' THEN
      NEW.resolved_at := now();
    ELSE
      NEW.status := 'open';
    END IF;
  ELSIF NEW.status <> 'done' THEN
    NEW.status := 'open';
  END IF;

  NEW.updated_at := now();
  NEW.last_seen  := COALESCE(NEW.last_seen, now());
  NEW.first_seen := COALESCE(NEW.first_seen, now());
  RETURN NEW;
END $$;


--
-- Name: child_consents_sync_legacy(); Type: FUNCTION; Schema: demo_eyfs; Owner: -
--

CREATE FUNCTION demo_eyfs.child_consents_sync_legacy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.consent_type = 'photo_media' THEN
    UPDATE demo_eyfs.children
       SET photo_consent = COALESCE(NEW.granted, false)
     WHERE id = NEW.child_id
       AND photo_consent IS DISTINCT FROM COALESCE(NEW.granted, false);
  ELSIF NEW.consent_type = 'marketing_face' THEN
    UPDATE demo_eyfs.children
       SET media_consent = COALESCE(NEW.granted, false)
     WHERE id = NEW.child_id
       AND media_consent IS DISTINCT FROM COALESCE(NEW.granted, false);
  END IF;
  RETURN NULL;   -- AFTER trigger; return value is ignored
END;
$$;


--
-- Name: paperwork_documents_tsv(); Type: FUNCTION; Schema: demo_eyfs; Owner: -
--

CREATE FUNCTION demo_eyfs.paperwork_documents_tsv() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.search_tsv :=
      setweight(to_tsvector('english', coalesce(NEW.title, '')), 'A')
    || setweight(to_tsvector('english',
         coalesce(NEW.category, '') || ' ' ||
         coalesce(NEW.subfolder, '') || ' ' ||
         coalesce(array_to_string(NEW.tags, ' '), '')), 'B')
    || setweight(to_tsvector('english', coalesce(NEW.summary, '')), 'C')
    || setweight(to_tsvector('english', left(coalesce(NEW.extracted_text, ''), 400000)), 'D');
  RETURN NEW;
END;
$$;


--
-- Name: wl_family_key(text, text, text); Type: FUNCTION; Schema: demo_eyfs; Owner: -
--

CREATE FUNCTION demo_eyfs.wl_family_key(p_first text, p_last text, p_email text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN COALESCE(btrim(p_first),'') <> '' OR COALESCE(btrim(p_last),'') <> ''
      THEN 'child:' || lower(btrim(COALESCE(p_first,''))) || '|' || lower(btrim(COALESCE(p_last,'')))
    WHEN COALESCE(btrim(p_email),'') <> ''
      THEN 'parent:' || lower(btrim(p_email))
    ELSE NULL
  END
$$;


