    provider text DEFAULT 'Swift'::text NOT NULL,
    start_date date,
    expected_end_date date,
    otj_target_hours numeric(7,2),
    prior_learning_hours numeric(7,2) DEFAULT 0 NOT NULL,
    planned_weekly_hours numeric(5,2),
    mentor_staff_id integer,
    status text DEFAULT 'active'::text NOT NULL,
    eportfolio text,
    notes text,
    created_by integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT apprenticeships_prior_chk CHECK ((prior_learning_hours >= (0)::numeric)),
    CONSTRAINT apprenticeships_status_chk CHECK ((status = ANY (ARRAY['active'::text, 'completed'::text, 'withdrawn'::text, 'paused'::text]))),
    CONSTRAINT apprenticeships_target_floor_chk CHECK (((otj_target_hours IS NULL) OR (otj_target_hours >= (187)::numeric)))
);


--
-- Name: CONSTRAINT apprenticeships_target_floor_chk ON apprenticeships; Type: COMMENT; Schema: demo_eyfs; Owner: -
--

COMMENT ON CONSTRAINT apprenticeships_target_floor_chk ON demo_eyfs.apprenticeships IS 'Apprenticeship funding rules 2026-27: recognition of prior learning must not bring the required hours below 187.';


