--

CREATE TABLE demo_eyfs.cctv_footage_requests (
    id integer NOT NULL,
    reference text,
    requester_type character varying(16) NOT NULL,
    requester_email text NOT NULL,
    requester_name text,
    requester_relationship text,
    requester_staff_id integer,
    child_id integer,
    request_date date DEFAULT CURRENT_DATE NOT NULL,
    incident_date date NOT NULL,
    incident_time_from time without time zone,
    incident_time_to time without time zone,
    incident_location text,
    reason text NOT NULL,
    identity_verified boolean,
    identity_verified_how text,
    identity_verified_by integer,
    identity_verified_at timestamp with time zone,
    third_parties_visible boolean,
    third_parties_note text,
    decision character varying(16),
    decision_reason text,
    decision_by integer,
    decision_at timestamp with time zone,
    responded_on date,
    response_due_date date NOT NULL,
    footage_expires_at timestamp with time zone NOT NULL,
    retention_days integer NOT NULL,
    preserve_status character varying(32) DEFAULT 'not_attempted'::character varying NOT NULL,
    preserve_attempted_at timestamp with time zone,
    preserve_error text,
    clip_path text,
    clip_bytes bigint,
    clip_verified_at timestamp with time zone,
    status character varying(16) DEFAULT 'submitted'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT cctv_req_decision_chk CHECK (((decision IS NULL) OR ((decision)::text = ANY (ARRAY[('disclose'::character varying)::text, ('redact'::character varying)::text, ('refuse'::character varying)::text])))),
    CONSTRAINT cctv_req_preserve_chk CHECK (((preserve_status)::text = ANY (ARRAY[('not_attempted'::character varying)::text, ('disabled'::character varying)::text, ('pending'::character varying)::text, ('failed'::character varying)::text, ('unavailable'::character varying)::text, ('expired'::character varying)::text, ('preserved'::character varying)::text]))),
    CONSTRAINT cctv_req_preserved_needs_clip_chk CHECK ((((preserve_status)::text <> 'preserved'::text) OR ((clip_path IS NOT NULL) AND (clip_verified_at IS NOT NULL)))),
    CONSTRAINT cctv_req_requester_type_chk CHECK (((requester_type)::text = ANY (ARRAY[('parent'::character varying)::text, ('staff'::character varying)::text]))),
    CONSTRAINT cctv_req_status_chk CHECK (((status)::text = ANY (ARRAY[('submitted'::character varying)::text, ('in_review'::character varying)::text, ('decided'::character varying)::text, ('closed'::character varying)::text])))
);


