--
-- Name: child_room_drift; Type: VIEW; Schema: demo_eyfs; Owner: -
--

CREATE VIEW demo_eyfs.child_room_drift AS
 SELECT c.id AS child_id,
    c.room_id AS profile_room_id,
    cr.name AS profile_room,
    b.id AS booking_id,
    b.room_id AS booking_room_id,
    br.name AS booking_room,
    b.start_date,
    b.end_date
   FROM (((demo_eyfs.children c
     JOIN demo_eyfs.child_bookings b ON ((b.child_id = c.id)))
     LEFT JOIN demo_eyfs.rooms cr ON ((cr.id = c.room_id)))
     LEFT JOIN demo_eyfs.rooms br ON ((br.id = b.room_id)))
  WHERE (COALESCE(c.is_active, true) AND (b.is_active = true) AND ((b.end_date IS NULL) OR (b.end_date >= CURRENT_DATE)) AND (b.start_date <= CURRENT_DATE) AND (c.room_id IS NOT NULL) AND (b.room_id IS DISTINCT FROM c.room_id));


