    difficulty smallint DEFAULT 2 NOT NULL,
    source_ref text
);


--
-- Name: knowledge_questions; Type: VIEW; Schema: demo_eyfs; Owner: -
--

CREATE VIEW demo_eyfs.knowledge_questions AS
 SELECT b.id,
    kt.id AS topic_id,
    kt.topic_key,
    kt.pop_slug AS topic_slug,
    b.quiz_key,
    b.question,
    b.options,
    b.correct AS correct_index,
    b.explain AS explanation,
    b.difficulty,
    b.source_ref,
    b.active
   FROM (demo_eyfs.reflection_quiz_bank b
     JOIN demo_eyfs.knowledge_topics kt ON (((kt.topic_key)::text = (b.topic)::text)));


