--

CREATE TABLE demo_eyfs.manager_decision_rights (
    id integer NOT NULL,
    topic_key text NOT NULL,
    topic text NOT NULL,
    modes text[] DEFAULT ARRAY['away'::text] NOT NULL,
    decided_by text NOT NULL,
    escalate_to text,
    wait_for_toby boolean DEFAULT false NOT NULL,
    urgency text DEFAULT 'normal'::text NOT NULL,
    basis text,
    notes text,
    approved boolean DEFAULT false NOT NULL,
    approved_by integer,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    match_terms text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT manager_decision_rights_urgency_check CHECK ((urgency = ANY (ARRAY['emergency'::text, 'today'::text, 'normal'::text, 'can_wait'::text])))
);


--
-- Name: COLUMN manager_decision_rights.match_terms; Type: COMMENT; Schema: demo_eyfs; Owner: -
--

COMMENT ON COLUMN demo_eyfs.manager_decision_rights.match_terms IS 'b512 — the phrases that route a question to this row. Scored on these ONLY (not on the topic prose), because one common word in the topic text was enough to send a raised voice to the LADO. Tune with an UPDATE; no deploy needed.';


