    source text DEFAULT 'manual'::text NOT NULL,
    source_ref integer,
    created_by integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT otj_entries_minutes_chk CHECK (((minutes > 0) AND (minutes <= 1440))),
    CONSTRAINT otj_entries_new_chk CHECK ((length(btrim(what_was_new)) >= 10)),
    CONSTRAINT otj_entries_paid_chk CHECK (((in_paid_hours = true) OR (compensated = true))),
    CONSTRAINT otj_entries_source_chk CHECK ((source = ANY (ARRAY['manual'::text, 'workbook'::text]))),
    CONSTRAINT otj_entries_type_chk CHECK ((activity_type = ANY (ARRAY['theory'::text, 'practical'::text, 'shadowing'::text, 'mentoring'::text, 'online'::text, 'simulation'::text, 'assignment'::text, 'revision'::text, 'learning_support'::text, 'industry_visit'::text])))
);


--
-- Name: CONSTRAINT otj_entries_paid_chk ON otj_entries; Type: COMMENT; Schema: demo_eyfs; Owner: -
--

COMMENT ON CONSTRAINT otj_entries_paid_chk ON demo_eyfs.otj_entries IS 'Off-the-job training must take place in normal working hours. By exception it may fall outside them only if the apprentice agreed and was compensated (TOIL or additional payment).';


