CREATE TABLE demo_eyfs.planning_activities (
    id integer NOT NULL,
    title character varying NOT NULL,
    description text,
    age_group character varying,
    duration_minutes integer,
    eyfs_areas text[],
    learning_objectives text[],
    materials_needed text[],
    setup_instructions text,
    step_by_step text,
    extension_ideas text,
    sen_adaptations text,
    risk_notes text,
    photo_paths text[],
    created_by character varying,
    tags text[],
    difficulty character varying,
    times_used integer DEFAULT 0,
    last_used_at timestamp with time zone,
    favourited_by text[] DEFAULT '{}'::text[],
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    edition text[] DEFAULT '{eyfs}'::text[],
    age_band text[] DEFAULT '{2-5}'::text[],
    setting text[] DEFAULT '{either}'::text[],
    source text DEFAULT 'wren-curated'::text,
    group_size text,
    area_of_learning text[],
    subject text[],
    curriculum_links text[],
    send_areas text[] DEFAULT '{}'::text[],
    is_public boolean DEFAULT true,
    share_to_community boolean DEFAULT false,
    source_school_id integer,
    ai_extension_prompts text[],
    CONSTRAINT planning_activities_age_group_check CHECK (((age_group)::text = ANY (ARRAY[('baby'::character varying)::text, ('toddler'::character varying)::text, ('preschool'::character varying)::text, ('mixed'::character varying)::text]))),
    CONSTRAINT planning_activities_difficulty_check CHECK (((difficulty)::text = ANY (ARRAY[('easy'::character varying)::text, ('moderate'::character varying)::text, ('challenging'::character varying)::text])))
);


