--
-- Name: policy_drafts; Type: TABLE; Schema: demo_eyfs; Owner: -
--

CREATE TABLE demo_eyfs.policy_drafts (
    id integer NOT NULL,
    build character varying(20) DEFAULT 'b236'::character varying NOT NULL,
    slug character varying(80) NOT NULL,
    policy_id integer,
    new_title text,
    new_category text,
    kind character varying(20) NOT NULL,
    framework character varying(40) DEFAULT 'eyfs_statutory_2026'::character varying NOT NULL,
    statement_codes text[] DEFAULT '{}'::text[] NOT NULL,
    driver character varying(20) NOT NULL,
    title text NOT NULL,
    rationale text NOT NULL,
    before_text text,
    after_text text NOT NULL,
    procedure_note text,
    confidence character varying(20) DEFAULT 'verify'::character varying NOT NULL,
    model character varying(60),
    prompt_note text,
    sort_order integer DEFAULT 100 NOT NULL,
    status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    decided_by integer,
    decided_at timestamp with time zone,
    decision_note text,
    edited_text text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT policy_drafts_conf_chk CHECK (((confidence)::text = ANY (ARRAY[('verify'::character varying)::text, ('clear'::character varying)::text]))),
    CONSTRAINT policy_drafts_driver_chk CHECK (((driver)::text = ANY (ARRAY[('new_2026'::character varying)::text, ('pre_existing'::character varying)::text, ('record_defect'::character varying)::text]))),
    CONSTRAINT policy_drafts_kind_chk CHECK (((kind)::text = ANY (ARRAY[('redline'::character varying)::text, ('new_policy'::character varying)::text]))),
    CONSTRAINT policy_drafts_status_chk CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('accepted'::character varying)::text, ('rejected'::character varying)::text, ('edited'::character varying)::text]))),
    CONSTRAINT policy_drafts_target_chk CHECK (((((kind)::text = 'redline'::text) AND (policy_id IS NOT NULL)) OR (((kind)::text = 'new_policy'::text) AND (new_title IS NOT NULL))))
);


