--

CREATE TABLE demo_eyfs.reports_triage (
    source text NOT NULL,
    source_id bigint NOT NULL,
    status text DEFAULT 'new'::text NOT NULL,
    report_type text,
    severity text,
    area text,
    assignee_staff_id integer,
    notes text,
    fixed_at timestamp with time zone,
    reporter_notified_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by integer,
    CONSTRAINT reports_triage_area_check CHECK (((area IS NULL) OR (area = ANY (ARRAY['ey'::text, 'parents'::text, 'roost'::text, 'hr'::text, 'landing'::text, 'other'::text])))),
    CONSTRAINT reports_triage_severity_check CHECK (((severity IS NULL) OR (severity = ANY (ARRAY['critical'::text, 'high'::text, 'medium'::text, 'low'::text])))),
    CONSTRAINT reports_triage_status_check CHECK ((status = ANY (ARRAY['new'::text, 'triaged'::text, 'in_progress'::text, 'fixed'::text, 'wont_fix'::text]))),
    CONSTRAINT reports_triage_type_check CHECK (((report_type IS NULL) OR (report_type = ANY (ARRAY['bug'::text, 'feature'::text, 'question'::text, 'praise'::text]))))
);


--
-- Name: reports_inbox; Type: VIEW; Schema: demo_eyfs; Owner: -
--

CREATE VIEW demo_eyfs.reports_inbox AS
 SELECT ('staff-app:'::text || f.id) AS key,
    'staff-app'::text AS source,
    (f.id)::bigint AS source_id,
    f.title,
    f.body,
    COALESCE(t.report_type,
        CASE f.kind
            WHEN 'bug'::text THEN 'bug'::text
            WHEN 'idea'::text THEN 'feature'::text
            WHEN 'works'::text THEN 'praise'::text
            ELSE 'question'::text
        END) AS report_type,
    COALESCE(t.status,
        CASE f.status
            WHEN 'new'::text THEN 'new'::text
            WHEN 'triaged'::text THEN 'triaged'::text
            WHEN 'in_progress'::text THEN 'in_progress'::text
            WHEN 'done'::text THEN 'fixed'::text
            WHEN 'dismissed'::text THEN 'wont_fix'::text
            ELSE 'new'::text
        END) AS status,
    t.severity,
    COALESCE(t.area,
        CASE lower(COALESCE(f.portal, ''::text))
            WHEN 'admin'::text THEN 'roost'::text
            WHEN 'hr'::text THEN 'hr'::text
            WHEN 'parents'::text THEN 'parents'::text
            WHEN 'learning'::text THEN 'ey'::text
            WHEN 'ey'::text THEN 'ey'::text
            ELSE 'other'::text
        END) AS area,
    t.assignee_staff_id,
    t.notes,
    t.fixed_at,
    t.reporter_notified_at,
    f.submitted_by_name AS reporter_name,
    f.submitted_by_email AS reporter_email,
    f.submitted_by AS reporter_staff_id,
    NULL::integer AS reporter_child_id,
    f.page_path,
    (f.screenshot_path IS NOT NULL) AS has_screenshot,
    f.created_at
   FROM (demo_eyfs.feedback_reports f
     LEFT JOIN demo_eyfs.reports_triage t ON (((t.source = 'staff-app'::text) AND (t.source_id = f.id))))
UNION ALL
 SELECT ('parent-app:'::text || p.id) AS key,
    'parent-app'::text AS source,
    (p.id)::bigint AS source_id,
    "left"(split_part(COALESCE(p.body, ''::text), '
'::text, 1), 120) AS title,
    p.body,
    COALESCE(t.report_type,
        CASE p.category
            WHEN 'bug'::text THEN 'bug'::text
            WHEN 'idea'::text THEN 'feature'::text
            WHEN 'change'::text THEN 'feature'::text
            WHEN 'like'::text THEN 'praise'::text
            ELSE 'question'::text
        END) AS report_type,
    COALESCE(t.status,
        CASE p.status
            WHEN 'new'::text THEN 'new'::text
            WHEN 'reviewed'::text THEN 'triaged'::text
            WHEN 'actioned'::text THEN 'fixed'::text
            WHEN 'dismissed'::text THEN 'wont_fix'::text
            ELSE 'new'::text
        END) AS status,
    t.severity,
    COALESCE(t.area, 'parents'::text) AS area,
    t.assignee_staff_id,
    t.notes,
    t.fixed_at,
    t.reporter_notified_at,
    NULLIF(p.parent_email, ''::text) AS reporter_name,
    p.parent_email AS reporter_email,
    NULL::integer AS reporter_staff_id,
    p.child_id AS reporter_child_id,
    p.page_context AS page_path,
    false AS has_screenshot,
    p.created_at
   FROM (demo_eyfs.parent_app_feedback p
     LEFT JOIN demo_eyfs.reports_triage t ON (((t.source = 'parent-app'::text) AND (t.source_id = p.id))))
UNION ALL
 SELECT ('getwren:'::text || g.id) AS key,
    'getwren'::text AS source,
    g.id AS source_id,
    "left"(split_part(COALESCE(g.message, ''::text), '
'::text, 1), 120) AS title,
    g.message AS body,
    COALESCE(t.report_type, 'question'::text) AS report_type,
    COALESCE(t.status,
        CASE
            WHEN (g.handled_at IS NOT NULL) THEN 'fixed'::text
            ELSE 'new'::text
        END) AS status,
    t.severity,
    COALESCE(t.area, 'landing'::text) AS area,
    t.assignee_staff_id,
    t.notes,
    t.fixed_at,
    t.reporter_notified_at,
    g.name AS reporter_name,
    g.email AS reporter_email,
    NULL::integer AS reporter_staff_id,
    NULL::integer AS reporter_child_id,
    g.source_page AS page_path,
    false AS has_screenshot,
    g.created_at
   FROM (demo_eyfs.getwren_leads g
     LEFT JOIN demo_eyfs.reports_triage t ON (((t.source = 'getwren'::text) AND (t.source_id = g.id))))
  WHERE (g.kind = 'feedback'::text)
UNION ALL
 SELECT ('manual:'::text || m.id) AS key,
    'manual'::text AS source,
    (m.id)::bigint AS source_id,
    m.title,
    m.body,
    COALESCE(t.report_type, m.report_type) AS report_type,
    COALESCE(t.status, 'new'::text) AS status,
    COALESCE(t.severity, m.severity) AS severity,
    COALESCE(t.area, m.area, 'other'::text) AS area,
    t.assignee_staff_id,
    t.notes,
    t.fixed_at,
    t.reporter_notified_at,
    m.reporter_name,
    m.reporter_email,
    m.reporter_staff_id,
    NULL::integer AS reporter_child_id,
    m.page_path,
    (m.screenshot_path IS NOT NULL) AS has_screenshot,
    m.created_at
   FROM (demo_eyfs.bug_reports_manual m
     LEFT JOIN demo_eyfs.reports_triage t ON (((t.source = 'manual'::text) AND (t.source_id = m.id))));


