    is_automatic boolean DEFAULT false NOT NULL,
    auto_close_reason text
);


--
-- Name: staff_clock_events_current; Type: VIEW; Schema: demo_eyfs; Owner: -
--

CREATE VIEW demo_eyfs.staff_clock_events_current AS
 SELECT id,
    staff_id,
    event_type,
    method,
    fob_uid,
    door_name,
    event_time,
    confidence,
    source_raw,
    created_at,
    device_id,
    source,
    fob_hash,
    recorded_by,
    corrects_event_id,
    correction_reason,
    query_id,
    is_automatic,
    auto_close_reason
   FROM demo_eyfs.staff_clock_events e
  WHERE (((event_type)::text <> 'clock_void'::text) AND (NOT (EXISTS ( SELECT 1
           FROM demo_eyfs.staff_clock_events c
          WHERE (c.corrects_event_id = e.id)))));


