--
-- Name: tasks; Type: TABLE; Schema: demo_eyfs; Owner: -
--

CREATE TABLE demo_eyfs.tasks (
    id integer NOT NULL,
    title text NOT NULL,
    description text,
    status text DEFAULT 'open'::text NOT NULL,
    priority text DEFAULT 'medium'::text NOT NULL,
    due_date date,
    owner_staff_id integer,
    created_by integer,
    source text DEFAULT 'manual'::text,
    source_ref text,
    linked_to text,
    linked_id integer,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    completed_at timestamp with time zone,
    time_of_day character varying(5),
    room_id integer,
    repeat_rule text,
    repeat_every integer DEFAULT 1,
    repeat_until date,
    repeat_parent_id integer,
    recurrence_spawned_at timestamp with time zone,
    escalated_at timestamp with time zone,
    completion_note text,
    context text,
    pinned_by integer,
    pinned_at timestamp with time zone,
    category text DEFAULT 'nursery'::text NOT NULL,
    sort_order integer,
    mode text DEFAULT 'quick'::text NOT NULL,
    is_project boolean DEFAULT false NOT NULL,
    parent_task_id integer,
    start_date date,
    smart_specific text,
    smart_measurable text,
    smart_achievable text,
    smart_relevant text,
    relevant_kind text,
    relevant_ref text,
    evidence_required boolean DEFAULT false NOT NULL,
    skip_non_open_days boolean DEFAULT false NOT NULL,
    assignee_spec jsonb,
    archived_at timestamp with time zone,
    CONSTRAINT tasks_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT tasks_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_progress'::text, 'done'::text, 'cancelled'::text]))),
    CONSTRAINT tasks_time_of_day_check CHECK (((time_of_day IS NULL) OR ((time_of_day)::text ~ '^[0-2][0-9]:[0-5][0-9]$'::text)))
);


