--
-- Name: v_allocation_periods; Type: VIEW; Schema: demo_eyfs; Owner: -
--

CREATE VIEW demo_eyfs.v_allocation_periods AS
 SELECT a.id AS allocation_id,
    a.payment_id,
    a.invoice_id,
    a.child_id,
    a.amount_pence,
    a.allocated_on,
    a.source,
    COALESCE(a.period_year, i.period_year, (EXTRACT(year FROM i.issued_on))::integer) AS period_year,
    COALESCE(a.period_month, i.period_month, (EXTRACT(month FROM i.issued_on))::integer) AS period_month,
    COALESCE(a.period_source, 'derived_at_read'::text) AS period_source,
    p.paid_on,
    p.payment_method,
    p.status AS payment_status,
    i.room_id,
    i.status AS invoice_status
   FROM ((demo_eyfs.payment_allocations a
     LEFT JOIN demo_eyfs.invoices i ON ((i.id = a.invoice_id)))
     LEFT JOIN demo_eyfs.payments p ON ((p.id = a.payment_id)));


--
-- Name: v_money_on_account; Type: VIEW; Schema: demo_eyfs; Owner: -
--

CREATE VIEW demo_eyfs.v_money_on_account AS
 SELECT p.id AS payment_id,
    p.child_id,
    p.amount_pence AS received_pence,
    COALESCE(al.allocated_pence, (0)::bigint) AS allocated_pence,
    (p.amount_pence - COALESCE(al.allocated_pence, (0)::bigint)) AS on_account_pence,
    COALESCE(p.paid_on, (p.created_at)::date) AS received_on,
    p.payment_method,
    p.status
   FROM (demo_eyfs.payments p
     LEFT JOIN ( SELECT payment_allocations.payment_id,
            sum(payment_allocations.amount_pence) AS allocated_pence
           FROM demo_eyfs.payment_allocations
          GROUP BY payment_allocations.payment_id) al ON ((al.payment_id = p.id)))
  WHERE ((p.status <> ALL (ARRAY['failed'::text, 'cancelled'::text, 'refunded'::text])) AND ((p.amount_pence - COALESCE(al.allocated_pence, (0)::bigint)) <> 0));


