CREATE TABLE demo_eyfs.viewings (
    id integer NOT NULL,
    room_id integer NOT NULL,
    slot_date date NOT NULL,
    start_time text NOT NULL,
    end_time text NOT NULL,
    status text DEFAULT 'requested'::text NOT NULL,
    family_type text NOT NULL,
    family_id integer NOT NULL,
    requested_via text DEFAULT 'staff'::text NOT NULL,
    requested_by integer,
    requested_at timestamp with time zone DEFAULT now(),
    confirmed_by integer,
    confirmed_at timestamp with time zone,
    declined_by integer,
    declined_at timestamp with time zone,
    decline_reason text,
    cancelled_by integer,
    cancelled_at timestamp with time zone,
    attendance_marked_by integer,
    attendance_marked_at timestamp with time zone,
    notes text,
    event_id integer,
    confirmation_email_sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT viewings_family_type_check CHECK ((family_type = ANY (ARRAY['waiting_list'::text, 'enquiry'::text]))),
    CONSTRAINT viewings_requested_via_check CHECK ((requested_via = ANY (ARRAY['staff'::text, 'family'::text]))),
    CONSTRAINT viewings_status_check CHECK ((status = ANY (ARRAY['requested'::text, 'confirmed'::text, 'declined'::text, 'cancelled'::text, 'attended'::text, 'no_show'::text])))
);


