--
-- Name: COLUMN waiting_list.family_key; Type: COMMENT; Schema: demo_eyfs; Owner: -
--

COMMENT ON COLUMN demo_eyfs.waiting_list.family_key IS 'b289 dedupe key for automated write paths. NULL = manually entered, never deduped.';


--
-- Name: COLUMN waiting_list.merged_into_id; Type: COMMENT; Schema: demo_eyfs; Owner: -
--

COMMENT ON COLUMN demo_eyfs.waiting_list.merged_into_id IS 'b289: this row was merged into waiting_list.id = this value. The row is kept, not deleted. Read paths must exclude it.';


--
-- Name: COLUMN waiting_list.room_source; Type: COMMENT; Schema: demo_eyfs; Owner: -
--

COMMENT ON COLUMN demo_eyfs.waiting_list.room_source IS 'b289: how room_needed got its value — import | derived | manual.';


