--
-- Name: waiting_list_live; Type: VIEW; Schema: demo_eyfs; Owner: -
--

CREATE VIEW demo_eyfs.waiting_list_live AS
 SELECT id,
    child_first_name,
    child_last_name,
    child_dob,
    room_needed,
    expected_start_date,
    parent_name,
    parent_email,
    parent_phone,
    source,
    status,
    notes,
    date_added,
    created_at,
    added_at,
    priority,
    fit_score,
    enquiry_id,
    tier,
    days_needed,
    preferred_days,
    min_days,
    deposit_paid,
    deposit_amount_pence,
    ready_reserve,
    offer_made_at,
    offer_expires_at,
    offer_status,
    seat_depth,
    last_contacted_at,
    last_contacted_by,
    flexible_start,
    flexible_parttime,
    how_heard,
    existing_family,
    list_duration_months,
    auto_action,
    private_notes,
    wren_thoughts,
    wren_thoughts_at,
    priority_score,
    eylog_ref,
    contact_state,
    last_contact_method,
    family_key,
    merged_into_id,
    merged_at,
    merged_by,
    room_source
   FROM demo_eyfs.waiting_list
  WHERE (merged_into_id IS NULL);


